import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
const contract = JSON.parse(readFileSync(process.argv[1], "utf8"));
assert.equal(contract.count, 52);
assert.equal(contract.names.length, 52);
assert.equal(new Set(contract.names).size, 52);
const expected = [...contract.names].sort();
const api = await import(pathToFileURL(resolve("src/index.ts")).href);
const definitions = api.createAgentCommands().map(command => command.name).sort();
assert.deepEqual(definitions, expected, "factory must expose the independently pinned 52 default names");
const shell = new api.Shell({ fs: api.createMemoryFileSystem() }).use(api.agentCommands());
try {
  const initialized = await shell.exec(":");
  assert.equal(initialized.exitCode, 0, initialized.stderr);
  const installed = shell.commands.list().map(command => command.name).sort();
  assert.deepEqual(installed, expected, "initialized host must expose the independently pinned 52 default names");
  assert.equal(new Set(installed).size, 52);
  for (const name of contract.forbiddenDefaultNames) assert.equal(installed.includes(name), false, name);
  console.log(JSON.stringify({ kind: "separate-exact-registry-probe", expected, definitions, installed, count: installed.length }));
} finally { await shell.dispose(); }
